def load_sector(ticker):
    df = pd.read_csv(f"data/raw/{ticker}.us.csv", parse_dates=["Date"])
    df = df.rename(columns=str.lower).set_index("date").sort_index()
    if ticker in LAUNCH:
        df = df[df.index >= LAUNCH[ticker]]
    return df[["open","high","low","close","volume"]]
